from itertools import combinations

def find_golomb_ruler(num_marks, max_length=None):
    """Find a Golomb ruler with num_marks marks using brute force search."""
    if max_length is None:
        # Known optimal length for 6 marks is 17
        max_length = 20

    def is_golomb(marks):
        distances = set()
        for i, j in combinations(marks, 2):
            d = abs(i - j)
            if d in distances:
                return False
            distances.add(d)
        return True

    # Use backtracking search
    def backtrack(marks, start):
        if len(marks) == num_marks:
            return marks[:]

        for next_mark in range(start, max_length + 1):
            # Check if adding next_mark maintains Golomb property
            new_distances = set()
            valid = True
            existing_distances = set()
            for i in range(len(marks)):
                for j in range(i+1, len(marks)):
                    existing_distances.add(marks[j] - marks[i])

            for m in marks:
                d = next_mark - m
                if d in existing_distances or d in new_distances:
                    valid = False
                    break
                new_distances.add(d)

            if valid:
                marks.append(next_mark)
                result = backtrack(marks, next_mark + 1)
                if result is not None:
                    return result
                marks.pop()

        return None

    result = backtrack([0], 1)
    return result

# Find a 6-mark Golomb ruler
ruler = find_golomb_ruler(6, max_length=20)
print(f"Found Golomb ruler: {ruler}")

# Verify it
if ruler:
    distances = []
    for i, j in combinations(ruler, 2):
        distances.append(abs(i - j))
    print(f"All pairwise distances: {sorted(distances)}")
    print(f"Number of distances: {len(distances)}")
    print(f"All unique: {len(distances) == len(set(distances))}")
    print(f"Number of marks: {len(ruler)}")
